"""Activation functions implemented as layers.
"""

from __future__ import annotations

import numpy as np
from .base import BaseLayer


class ReLU(BaseLayer):
    def __init__(self):
        super().__init__()

    def forward(self, x: np.ndarray) -> np.ndarray:
        return np.maximum(0, x.astype(np.float64, copy=False))


class LeakyReLU(BaseLayer):
    def __init__(self, negative_slope: float = 0.01):
        super().__init__()
        self.negative_slope = negative_slope

    def forward(self, x: np.ndarray) -> np.ndarray:
        x = x.astype(np.float64, copy=False)
        return np.where(x > 0, x, self.negative_slope * x)


class Sigmoid(BaseLayer):
    def __init__(self):
        super().__init__()

    def forward(self, x: np.ndarray) -> np.ndarray:
        x = x.astype(np.float64, copy=False)
        # Numerically stable sigmoid
        pos_mask = x >= 0
        neg_mask = ~pos_mask
        result = np.empty_like(x, dtype=np.float64)
        result[pos_mask] = 1 / (1 + np.exp(-x[pos_mask]))
        exp_x = np.exp(x[neg_mask])
        result[neg_mask] = exp_x / (1 + exp_x)
        return result
